SELECT id, full_name, dept_id, hire_date, FIRST_VALUE(job_title) IGNORE NULLS OVER (PARTITION BY manager_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_job_title, SUM(salary) OVER (ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, ROW_NUMBER() OVER w_grp AS event_seq FROM employees WINDOW w_grp AS (PARTITION BY dept_id, level ORDER BY hire_date, id);
